import sys
import time

sys.path.insert(0, "/etc/replaybook/lib")

import common

common.init_db()


def process_batch():
    conn = common.get_conn()
    rows = conn.execute(
        "SELECT id, payload FROM jobs WHERE status='accepted' LIMIT 50"
    ).fetchall()
    for job_id, payload in rows:
        result = "processed:" + payload
        conn.execute(
            "UPDATE jobs SET status='completed', result=?, attempts=attempts+1 "
            "WHERE id=? AND status='accepted'",
            (result, job_id),
        )
        conn.commit()
    conn.close()
    return len(rows)


if __name__ == "__main__":
    while True:
        try:
            n = process_batch()
        except Exception:
            n = 0
            time.sleep(1)
            continue
        time.sleep(0.2 if n == 0 else 0)

